// 气血上限 / 法力上限 以 MVU 变量中存储的值为准（由变量更新规则维护）。
// 旧存档或规则尚未写入时（上限缺失或非正数），按六维公式派生仅用于显示兜底；
// 变量的正确上限由角色卡守护脚本在恢复权威六维后回填，前端不主动写回派生上限。

export type 当前气血法力Like = {
  气血?: unknown;
  法力值?: unknown;
  气血上限?: unknown;
  法力值上限?: unknown;
  六维?: { 体魄?: unknown; 灵力?: unknown; 根骨?: unknown } | undefined | null;
};

const num = (v: unknown): number => {
  const n = Number(v);
  return Number.isFinite(n) ? n : 0;
};

/** 气血上限 = 50 + 体魄×10 + 根骨×5 */
export function deriveMaxHp(六维: 当前气血法力Like['六维']): number {
  return 50 + num(六维?.体魄) * 10 + num(六维?.根骨) * 5;
}

/** 法力上限 = 50 + 灵力×15 + 根骨×5 */
export function deriveMaxMp(六维: 当前气血法力Like['六维']): number {
  return 50 + num(六维?.灵力) * 15 + num(六维?.根骨) * 5;
}

/** 读取变量中存储的气血上限；缺失或非正数时按六维派生兜底。 */
export function readMaxHp(data: 当前气血法力Like): number {
  const stored = num(data?.气血上限);
  return stored > 0 ? stored : deriveMaxHp(data?.六维);
}

/** 读取变量中存储的法力值上限；缺失或非正数时按六维派生兜底。 */
export function readMaxMp(data: 当前气血法力Like): number {
  const stored = num(data?.法力值上限);
  return stored > 0 ? stored : deriveMaxMp(data?.六维);
}

/** 显示用当前值：clamp 到 [0, 上限] */
export function clampCurrent(current: unknown, max: number): number {
  const n = num(current);
  return Math.max(0, Math.min(n, max));
}

/** 保持合法当前值不变，仅将越界的气血与法力截断到有效上限（存储优先，缺失/非法时按六维派生）。 */
export function clampVitalsToDerivedMax(data: 当前气血法力Like): { 气血: number; 法力值: number } {
  return {
    气血: clampCurrent(data.气血, readMaxHp(data)),
    法力值: clampCurrent(data.法力值, readMaxMp(data)),
  };
}
